    "description": "File a claim for theft peril with incident_date 2025-02-10, policy_id HM-448120, description 'Bicycles stolen from the garage', and estimate_usd 1800."
  },
  "applicable_norms": [
    {
      "policy_source_id": "q12",
      "interpretation": "A claim can be filed with `file_claim` only if: (1) the policy status is `active`, and the incident date is within the coverage period (`effective_from` ≤ incident date ≤ `effective_to`); (2) the claim is filed no later than 60 days after the incident date; (3) the peril is covered by the policy.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q12",
      "interpretation": "Before `file_claim`, summarize the details (including amounts) and get explicit confirmation (\"yes\"/\"да\").",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q12",
      "interpretation": "The `incident_date` must be the date stated by the policyholder, in YYYY-MM-DD format.",
      "modality": "REQUIRE"
    },
    {
      "policy_source_id": "q12",
      "interpretation": "Do not speculate on whether a future claim will be approved.",
      "modality": "FORBID"
    }
  ],
