    },
    {
      "source_id": "h30",
      "actor": "assistant",
      "role": "agent",
      "fact": "Assistant summarized the claim details (policy_id HM-448120, peril theft, incident_date 2025-02-10, description 'кража велосипедов из гаража', estimate_usd 1800) and requested confirmation."
    },
